-- Демо-данные (выполнять после schema.sql, из SQL Editor)
insert into organizers (name) values ('TechWave Events'), ('Код Будущего')
on conflict do nothing;

insert into petitions (title, event_name, organizer_id, body, body_ai_refined, category, status, author_attended, evidence_url)
select
  'Час в очереди на вход без проверки регистрации',
  'HackCity 2026',
  (select id from organizers where name = 'TechWave Events'),
  'Пришёл к 9:00 как было указано в письме. На входе никто не проверял QR и статус одобрения, толпа стояла больше часа, людей без регистрации пускали наравне со всеми. Внутри все столы были заняты людьми без ноутбуков, одобренным командам сесть было некуда.',
  E'1. Суть претензии\nУчастники с подтверждённой регистрацией не смогли своевременно начать работу из-за отсутствия контроля на входе.\n\n2. Обстоятельства\nВ 9:00, ко времени, указанному в письме-приглашении, у входа образовалась очередь; ожидание составило около часа. Проверка QR-кодов и статусов одобрения не проводилась.\n\n3. Выявленные нарушения\n— отсутствие проверки регистрации;\n— допуск лиц без подтверждённого статуса;\n— рабочие места заняты лицами, не участвующими в хакатоне.\n\n4. Последствия\nПотеря времени на старте, невозможность разместить команды.\n\n5. Требования\nПубличный ответ организатора, регламент входа с проверкой статусов, выделенные места для одобренных команд.',
  'logistics', 'collecting', true, 'https://example.com/photo.jpg'
where not exists (select 1 from petitions where title = 'Час в очереди на вход без проверки регистрации');
